-- Script to populate DQ images into the database
-- Dataset: System Avatar Images
-- Subject Area: System Avatars
-- Domain: Reference Data
--
-- This file was auto-generated from the image files in external/avatars
-- by images_generate_sql.py
--
-- To regenerate, run:
--   python3 images_generate_sql.py --config <config_name>
-- or with explicit parameters:
--   python3 images_generate_sql.py --dataset-name "..." --subject-area "..." --domain "..." ...


DO $$
declare
    v_dataset_id uuid;
begin
    -- Get the dataset ID using (name, subject_area_name, domain_name)
    select id into v_dataset_id
    from ores_dq_datasets_tbl
    where name = 'System Avatar Images'
      and subject_area_name = 'System Avatars'
      and domain_name = 'Reference Data'
      and valid_to = ores_utility_infinity_timestamp_fn();

    if v_dataset_id is null then
        raise exception 'Dataset not found: name="System Avatar Images", subject_area="System Avatars", domain="Reference Data"';
    end if;

    -- Clear existing images for this dataset (idempotency)
    delete from ores_dq_images_artefact_tbl
    where dataset_id = v_dataset_id;

    raise debug 'Populating images for dataset: %', 'System Avatar Images';

    -- Insert images
    insert into ores_dq_images_artefact_tbl (
        dataset_id, tenant_id, image_id, version, key, description, mime_type, data
    ) values (
        v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 0, 'super_admin_avatar', 'Avatar of super_admin_avatar', 'image/png', $b64$$b64$
    );
    insert into ores_dq_images_artefact_tbl (
        dataset_id, tenant_id, image_id, version, key, description, mime_type, data
    ) values (
        v_dataset_id, ores_utility_system_tenant_id_fn(), gen_random_uuid(), 0, 'tenant_admin_avatar', 'Avatar of tenant_admin_avatar', 'image/png', $b64$$b64$
    );

    raise debug 'Successfully populated % images for dataset: %', 2, 'System Avatar Images';
end $$;
